  const LANGS = { en: "English", ta: "தமிழ்", hi: "हिन्दी" };
  const DICT = { en, ta, hi };
  let current = "en";

  function setLang(code) { current = DICT[code] ? code : "en"; return current; }
  function lang() { return current; }
  function t(key, params) {
    let s = (DICT[current] && DICT[current][key]) || en[key] || key;
    if (params) for (const [k, v] of Object.entries(params)) s = s.split("{" + k + "}").join(v);
    return s;
  }

  const api = { t, setLang, lang, LANGS, DICT };
  if (typeof module !== "undefined" && module.exports) module.exports = api;
  else root.CSI18N = api;
